, '    "b1": ['
, '      1,'
, '      2,'
, '      3,'
, '      4'
, '    ],'
, '    "b2": {'
, '      "c1": 1,'
, '      "c2": 2'
, '    }'
, '  },'
, '  "a2": "a2"'
